     1→/**
     2→ * CLAUDELang v6.0 Compiler
     3→ * CLAUDELang JSON → VT 바이트코드 변환
     4→ */
     5→
     6→class CLAUDELangCompiler {
     7→  constructor() {
     8→    this.scope = new Map(); // 변수 저장소
     9→    this.vtFunctions = new Map(); // VT 함수 목록
    10→    this.initializeVTFunctions();
    11→  }
    12→
    13→  /**
    14→   * VT 함수 목록 초기화
    15→   */
    16→  initializeVTFunctions() {
    17→    // HTTP (예)
    18→    this.registerFunction("HTTP.get", ["url: string"], "Object");
    19→    this.registerFunction("HTTP.post", ["url: string", "data: Object"], "Object");
    20→
    21→    // Array
    22→    this.registerFunction("Array.map", ["array: Array", "fn: Function"], "Array");
    23→    this.registerFunction("Array.filter", ["array: Array", "fn: Function"], "Array");
    24→    this.registerFunction("Array.reduce", ["array: Array", "fn: Function", "init: any"], "any");
    25→    this.registerFunction("Array.find", ["array: Array", "fn: Function"], "any");
    26→
    27→    // String
    28→    this.registerFunction("String.split", ["str: string", "delimiter: string"], "Array<string>");
    29→    this.registerFunction("String.join", ["arr: Array", "delimiter: string"], "string");
    30→    this.registerFunction("String.upper", ["str: string"], "string");
    31→    this.registerFunction("String.lower", ["str: string"], "string");
    32→    this.registerFunction("String.trim", ["str: string"], "string");
    33→
    34→    // Math
    35→    this.registerFunction("Math.sqrt", ["x: f64"], "f64");
    36→    this.registerFunction("Math.pow", ["x: f64", "y: f64"], "f64");
    37→    this.registerFunction("Math.abs", ["x: f64"], "f64");
    38→
    39→    // FileSystem
    40→    this.registerFunction("FS.read", ["path: string"], "string");
    41→    this.registerFunction("FS.write", ["path: string", "content: string"], "bool");
    42→    this.registerFunction("FS.exists", ["path: string"], "bool");
    43→
    44→    // JSON
    45→    this.registerFunction("JSON.parse", ["str: string"], "Object");
    46→    this.registerFunction("JSON.stringify", ["obj: Object"], "string");
    47→
    48→    // Markdown
    49→    this.registerFunction("Markdown.create", [], "Object");
    50→    this.registerFunction("Markdown.heading", ["doc: Object", "level: i32", "text: string"], "Object");
    51→    this.registerFunction("Markdown.paragraph", ["doc: Object", "text: string"], "Object");
    52→    this.registerFunction("Markdown.code", ["doc: Object", "lang: string", "code: string"], "Object");
    53→    this.registerFunction("Markdown.build", ["doc: Object"], "string");
    54→
    55→    // Notion
    56→    this.registerFunction("Notion.post", ["data: Object"], "Object");
    57→    this.registerFunction("Notion.query", ["database_id: string", "filter: Object"], "Array");
    58→
    59→    // Print (기본)
    60→    this.registerFunction("print", ["value: any"], "null");
    61→  }
    62→
    63→  registerFunction(name, params, returnType) {
    64→    this.vtFunctions.set(name, {
    65→      params: params,
    66→      returnType: returnType,
    67→    });
    68→  }
    69→
    70→  /**
    71→   * 주요 컴파일 함수
    72→   */
    73→  compile(claudelangJson) {
    74→    try {
    75→      // 1. 검증
    76→      this.validate(claudelangJson);
    77→
    78→      // 2. 타입 검사
    79→      this.typeCheck(claudelangJson);
    80→
    81→      // 3. VT 코드 생성
    82→      const vtCode = this.generateVTCode(claudelangJson);
    83→
    84→      return {
    85→        success: true,
    86→        code: vtCode,
    87→        errors: [],
    88→      };
    89→    } catch (error) {
    90→      return {
    91→        success: false,
    92→        code: null,
    93→        errors: [error.message],
    94→      };
    95→    }
    96→  }
    97→
    98→  /**
    99→   * 스키마 검증
   100→   */
   101→  validate(obj) {
   102→    if (!obj.version) {
   103→      throw new Error("Missing 'version' field");
   104→    }
   105→
   106→    if (obj.version !== "6.0") {
   107→      throw new Error(`Unsupported version: ${obj.version}`);
   108→    }
   109→
   110→    if (!Array.isArray(obj.instructions)) {
   111→      throw new Error("'instructions' must be an array");
   112→    }
   113→
   114→    obj.instructions.forEach((instr, idx) => {
   115→      if (!instr.type) {
   116→        throw new Error(`Instruction at line ${idx} missing 'type'`);
   117→      }
   118→
   119→      switch (instr.type) {
   120→        case "var":
   121→          if (!instr.name || !instr.value_type) {
   122→            throw new Error(`VarDeclaration at line ${idx} missing required fields`);
   123→          }
   124→          break;
   125→
   126→        case "call":
   127→          if (!instr.function || !Array.isArray(instr.args)) {
   128→            throw new Error(`CallInstruction at line ${idx} missing required fields`);
   129→          }
   130→          break;
   131→
   132→        case "condition":
   133→          if (!instr.test || !Array.isArray(instr.then)) {
   134→            throw new Error(`ConditionInstruction at line ${idx} missing required fields`);
   135→          }
   136→          break;
   137→
   138→        case "loop":
   139→          if (!instr.iterator || !instr.range || !Array.isArray(instr.body)) {
   140→            throw new Error(`LoopInstruction at line ${idx} missing required fields`);
   141→          }
   142→          break;
   143→
   144→        case "comment":
   145→          break;
   146→
   147→        default:
   148→          throw new Error(`Unknown instruction type at line ${idx}: ${instr.type}`);
   149→      }
   150→    });
   151→  }
   152→
   153→  /**
   154→   * 타입 검사
   155→   */
   156→  typeCheck(ast) {
   157→    this.scope.clear();
   158→
   159→    ast.instructions.forEach((instr, idx) => {
   160→      try {
   161→        this.checkInstruction(instr);
   162→      } catch (error) {
   163→        throw new Error(`Type error at instruction ${idx}: ${error.message}`);
   164→      }
   165→    });
   166→  }
   167→
   168→  checkInstruction(instr) {
   169→    switch (instr.type) {
   170→      case "var":
   171→        // 변수를 scope에 추가
   172→        this.scope.set(instr.name, instr.value_type);
   173→
   174→        // 초기값 타입이 있으면 검사
   175→        if (instr.value !== undefined) {
   176→          const exprType = this.inferType(instr.value);
   177→          if (!this.isCompatible(exprType, instr.value_type)) {
   178→            throw new Error(
   179→              `Cannot assign ${exprType} to ${instr.value_type}`
   180→            );
   181→          }
   182→        }
   183→        break;
   184→
   185→      case "call":
   186→        // 함수 존재 여부 확인
   187→        if (!this.vtFunctions.has(instr.function)) {
   188→          throw new Error(`Unknown function: ${instr.function}`);
   189→        }
   190→
   191→        // 함수 시그니처 검사
   192→        const signature = this.vtFunctions.get(instr.function);
   193→        if (instr.args.length !== signature.params.length) {
   194→          throw new Error(
   195→            `${instr.function} expects ${signature.params.length} arguments, got ${instr.args.length}`
   196→          );
   197→        }
   198→
   199→        // 반환값을 scope에 추가
   200→        if (instr.assign_to) {
   201→          this.scope.set(instr.assign_to, signature.returnType);
   202→        }
   203→        break;
   204→
   205→      case "condition":
   206→        // 조건 검사 (선택사항)
   207→        break;
   208→
   209→      case "loop":
   210→        // 범위 검사 (선택사항)
   211→        break;
   212→    }
   213→  }
   214→
   215→  inferType(expr) {
   216→    if (!expr) {
   217→      return "any";
   218→    }
   219→
   220→    // 기본 값 타입
   221→    if (typeof expr === "number") {
   222→      return "i32";
   223→    }
   224→    if (typeof expr === "string") {
   225→      return "string";
   226→    }
   227→    if (typeof expr === "boolean") {
   228→      return "bool";
   229→    }
   230→
   231→    if (expr.type === "literal") {
   232→      return expr.value_type || "any";
   233→    } else if (expr.type === "ref") {
   234→      if (!this.scope.has(expr.name)) {
   235→        // throw new Error(`Undefined variable: ${expr.name}`);
   236→        return "any"; // 선언되지 않은 변수는 any로 취급
   237→      }
   238→      return this.scope.get(expr.name);
   239→    } else if (expr.type === "arithmetic") {
   240→      return "f64"; // 간단한 추론
   241→    } else if (expr.type === "comparison") {
   242→      return "bool";
   243→    } else if (expr.type === "array") {
   244→      // 배열 요소 타입 추론
   245→      if (!expr.elements || expr.elements.length === 0) {
   246→        return "Array<any>";
   247→      }
   248→      // 첫 번째 요소의 타입을 배열 타입으로 사용
   249→      const elementType = this.inferType(expr.elements[0]);
   250→      return `Array<${elementType}>`;
   251→    } else if (expr.type === "object") {
   252→      return "Object";
   253→    } else if (expr.type === "lambda") {
   254→      return "Function";
   255→    } else if (expr.type === "call") {
   256→      if (this.vtFunctions.has(expr.function)) {
   257→        return this.vtFunctions.get(expr.function).returnType;
   258→      }
   259→      return "any";
   260→    }
   261→
   262→    return "any";
   263→  }
   264→
   265→  isCompatible(from, to) {
   266→    if (from === to) return true;
   267→    if (from === "any" || to === "any") return true;
   268→    if (from === "i32" && to === "f64") return true; // 정수 → 실수
   269→
   270→    // Generic type compatibility (e.g., Array<i32> to Array<i32>)
   271→    if (from.startsWith("Array<") && to.startsWith("Array<")) {
   272→      const fromElement = from.slice(6, -1); // Array<X> → X
   273→      const toElement = to.slice(6, -1);     // Array<Y> → Y
   274→      return this.isCompatible(fromElement, toElement);
   275→    }
   276→
   277→    return false;
   278→  }
   279→
   280→  /**
   281→   * VT 코드 생성
   282→   */
   283→  generateVTCode(ast) {
   284→    const lines = [
   285→      "; CLAUDELang v6.0 compiled to VT",
   286→      "; Generated code below",
   287→      "",
   288→    ];
   289→
   290→    ast.instructions.forEach((instr) => {
   291→      lines.push(this.generateInstruction(instr));
   292→    });
   293→
   294→    return lines.filter((line) => line !== null).join("\n");
   295→  }
   296→
   297→  generateInstruction(instr) {
   298→    switch (instr.type) {
   299→      case "var":
   300→        return this.generateVarDeclaration(instr);
   301→
   302→      case "call":
   303→        return this.generateCallInstruction(instr);
   304→
   305→      case "condition":
   306→        return this.generateConditionInstruction(instr);
   307→
   308→      case "loop":
   309→        return this.generateLoopInstruction(instr);
   310→
   311→      case "comment":
   312→        return `; ${instr.text}`;
   313→
   314→      default:
   315→        return null;
   316→    }
   317→  }
   318→
   319→  generateVarDeclaration(instr) {
   320→    let value;
   321→
   322→    // 값이 기본 타입(숫자, 문자열, 불린)이면 직접 처리
   323→    if (typeof instr.value === "number") {
   324→      value = instr.value.toString();
   325→    } else if (typeof instr.value === "string") {
   326→      value = `"${instr.value}"`;
   327→    } else if (typeof instr.value === "boolean") {
   328→      value = instr.value ? "true" : "false";
   329→    } else if (typeof instr.value === "object" && instr.value) {
   330→      // 객체/배열이면 표현식으로 처리
   331→      value = this.generateExpression(instr.value);
   332→    } else {
   333→      value = "null";
   334→    }
   335→
   336→    return `(define ${instr.name} ${value})`;
   337→  }
   338→
   339→  generateCallInstruction(instr) {
   340→    const args = instr.args.map((arg) => this.generateExpression(arg)).join(" ");
   341→    const callCode = `(call ${instr.function} ${args})`;
   342→
   343→    if (instr.assign_to) {
   344→      return `(define ${instr.assign_to} ${callCode})`;
   345→    } else {
   346→      return callCode;
   347→    }
   348→  }
   349→
   350→  generateExpression(expr) {
   351→    if (!expr) {
   352→      return "null";
   353→    }
   354→
   355→    // 기본 타입 처리
   356→    if (typeof expr === "number" || typeof expr === "boolean") {
   357→      return expr.toString();
   358→    }
   359→    if (typeof expr === "string") {
   360→      return `"${expr}"`;
   361→    }
   362→
   363→    // 객체/배열 타입 처리
   364→    if (typeof expr !== "object" || !expr.type) {
   365→      return "null";
   366→    }
   367→
   368→    switch (expr.type) {
   369→      case "literal":
   370→        if (expr.value_type === "string") {
   371→          return `"${expr.value}"`;
   372→        }
   373→        return expr.value !== undefined ? expr.value.toString() : "null";
   374→
   375→      case "ref":
   376→        return expr.name;
   377→
   378→      case "arithmetic":
   379→        const left = this.generateExpression(expr.left);
   380→        const right = this.generateExpression(expr.right);
   381→        return `(${expr.operator} ${left} ${right})`;
   382→
   383→      case "comparison":
   384→        const compLeft = this.generateExpression(expr.left);
   385→        const compRight = this.generateExpression(expr.right);
   386→        return `(${expr.operator} ${compLeft} ${compRight})`;
   387→
   388→      case "array":
   389→        if (!expr.elements || expr.elements.length === 0) {
   390→          return "(array)";
   391→        }
   392→        const elements = expr.elements
   393→          .map((e) => this.generateExpression(e))
   394→          .join(" ");
   395→        return `(array ${elements})`;
   396→
   397→      case "object":
   398→        const props = Object.entries(expr.properties)
   399→          .map(([key, value]) => `("${key}" ${this.generateExpression(value)})`)
   400→          .join(" ");
   401→        return `(object ${props})`;
   402→
   403→      case "lambda":
   404→        const params = expr.params ? expr.params.map((p) => p.name).join(" ") : "";
   405→        const bodyExpr = expr.body
   406→          .map((b) => {
   407→            // Check if it's an instruction or an expression
   408→            if (b.type === "arithmetic" || b.type === "comparison" || b.type === "ref" || b.type === "literal" || b.type === "call") {
   409→              return this.generateExpression(b);
   410→            } else {
   411→              return this.generateInstruction(b);
   412→            }
   413→          })
   414→          .filter((b) => b !== null)
   415→          .join(" ");
   416→        return `(fn (${params}) ${bodyExpr})`;
   417→
   418→      case "property":
   419→        const obj = this.generateExpression(expr.object);
   420→        return `(property ${obj} "${expr.property}")`;
   421→
   422→      case "index":
   423→        const array = this.generateExpression(expr.array);
   424→        const index = this.generateExpression(expr.index);
   425→        return `(index ${array} ${index})`;
   426→
   427→      default:
   428→        return "null";
   429→    }
   430→  }
   431→
   432→  generateConditionInstruction(instr) {
   433→    const test = this.generateExpression(instr.test);
   434→    const thenCode = instr.then
   435→      .map((i) => this.generateInstruction(i))
   436→      .filter((i) => i !== null)
   437→      .join(" ");
   438→    const elseCode = instr.else
   439→      ? instr.else
   440→          .map((i) => this.generateInstruction(i))
   441→          .filter((i) => i !== null)
   442→          .join(" ")
   443→      : "null";
   444→
   445→    return `(if ${test} (do ${thenCode}) (do ${elseCode}))`;
   446→  }
   447→
   448→  generateLoopInstruction(instr) {
   449→    const range = this.generateExpression(instr.range);
   450→    const body = instr.body
   451→      .map((i) => this.generateInstruction(i))
   452→      .filter((i) => i !== null)
   453→      .join(" ");
   454→
   455→    return `(for ${instr.iterator} ${range} (do ${body}))`;
   456→  }
   457→}
   458→
   459→// 내보내기
   460→if (typeof module !== "undefined" && module.exports) {
   461→  module.exports = CLAUDELangCompiler;
   462→}
   463→
   464→

