/**
 * CLAUDELang v6.0 Cached Compiler
 * 컴파일 결과 캐싱을 통한 성능 최적화
 *
 * 최적화:
 * 1. 전체 AST 캐싱
 * 2. 부분 컴파일 결과 캐싱
 * 3. 함수 시그니처 캐싱
 */

const crypto = require("crypto");
const CLAUDELangCompiler = require("./compiler.js");

class CachedCLAUDELangCompiler extends CLAUDELangCompiler {
  constructor(maxCacheSize = 1000) {
    super();
    this.cache = new Map(); // 컴파일 결과 캐시
    this.astCache = new Map(); // AST 파싱 결과 캐시
    this.maxCacheSize = maxCacheSize;
    this.cacheHits = 0;
    this.cacheMisses = 0;
  }

  /**
   * 입력 프로그램의 해시 생성
   * 동일한 입력을 빠르게 식별하기 위함
   */
  generateHash(data) {
    const str = JSON.stringify(data);
    return crypto.createHash("md5").update(str).digest("hex");
  }

  /**
   * 캐시 크기 관리 (LRU 정책)
   */
  evictIfNeeded() {
    if (this.cache.size > this.maxCacheSize) {
      // 가장 오래된 항목 제거
      const firstKey = this.cache.keys().next().value;
      this.cache.delete(firstKey);
    }
  }

  /**
   * 최적화된 컴파일 (캐싱 포함)
   */
  compile(claudelangJson) {
    // 입력 해시 생성
    const hash = this.generateHash(claudelangJson);

    // 캐시 확인
    if (this.cache.has(hash)) {
      this.cacheHits++;
      return this.cache.get(hash);
    }

    this.cacheMisses++;

    // 원본 컴파일 실행
    const result = super.compile(claudelangJson);

    // 결과 캐싱
    this.cache.set(hash, result);
    this.evictIfNeeded();

    return result;
  }

  /**
   * 검증만 캐싱 (빠른 검증)
   */
  validateCached(obj) {
    const hash = this.generateHash(obj);
    const cacheKey = `validate_${hash}`;

    if (this.cache.has(cacheKey)) {
      return true; // 이미 검증됨
    }

    try {
      super.validate(obj);
      this.cache.set(cacheKey, { validated: true });
      return true;
    } catch (error) {
      return false;
    }
  }

  /**
   * 부분 AST 캐싱을 통한 개별 명령어 컴파일
   */
  compileInstruction(instruction) {
    const hash = this.generateHash(instruction);
    const cacheKey = `instr_${hash}`;

    if (this.cache.has(cacheKey)) {
      this.cacheHits++;
      return this.cache.get(cacheKey);
    }

    this.cacheMisses++;

    try {
      const result = this.generateInstruction(instruction);
      this.cache.set(cacheKey, result);
      this.evictIfNeeded();
      return result;
    } catch (error) {
      return null;
    }
  }

  /**
   * 캐시 통계
   */
  getCacheStats() {
    const total = this.cacheHits + this.cacheMisses;
    const hitRate = total === 0 ? 0 : (this.cacheHits / total) * 100;

    return {
      cacheSize: this.cache.size,
      maxCacheSize: this.maxCacheSize,
      hits: this.cacheHits,
      misses: this.cacheMisses,
      total: total,
      hitRate: hitRate.toFixed(2) + "%",
      efficiency: ((this.cacheHits * 100) / (total || 1)).toFixed(2),
    };
  }

  /**
   * 캐시 초기화
   */
  clearCache() {
    this.cache.clear();
    this.cacheHits = 0;
    this.cacheMisses = 0;
  }

  /**
   * 캐시 상태 출력
   */
  printCacheStats() {
    const stats = this.getCacheStats();
    console.log("\n");
    console.log("╔" + "═".repeat(50) + "╗");
    console.log("║" + " Cache Statistics".padEnd(50) + "║");
    console.log("╠" + "═".repeat(50) + "╣");
    console.log(`║ Cache Size: ${stats.cacheSize}/${stats.maxCacheSize}`.padEnd(51) + "║");
    console.log(`║ Hits: ${stats.hits}, Misses: ${stats.misses}`.padEnd(51) + "║");
    console.log(`║ Hit Rate: ${stats.hitRate}`.padEnd(51) + "║");
    console.log("╚" + "═".repeat(50) + "╝\n");
  }
}

module.exports = CachedCLAUDELangCompiler;

/**
 * CLAUDELang v6.0 Optimized VT Runtime
 * VT 바이트코드 실행 엔진 (최적화 버전)
 *
 * 최적화:
 * 1. 메모리 풀 관리 (객체 재사용)
 * 2. 불필요한 복사 제거
 * 3. 변수 접근 최적화 (직접 참조)
 * 4. JIT 컴파일 준비 (미래 확장)
 */

class OptimizedVTRuntime {
  constructor(options = {}) {
    this.variables = new Map();
    this.functions = new Map();
    this.output = [];

    // 최적화 옵션
    this.options = {
      poolSize: options.poolSize || 1000,
      enableMemoryPool: options.enableMemoryPool !== false,
      enableDirectAccess: options.enableDirectAccess !== false,
      enableInlining: options.enableInlining !== false,
      ...options,
    };

    // 메모리 풀 초기화
    this.objectPool = [];
    this.arrayPool = [];
    this.stringPool = new Set();

    if (this.options.enableMemoryPool) {
      this.initializePools();
    }

    // 접근 최적화: 빈번하게 사용되는 변수 캐시
    this.accessCache = new Map();

    this.registerBuiltinFunctions();
  }

  /**
   * 메모리 풀 초기화
   */
  initializePools() {
    for (let i = 0; i < this.options.poolSize; i++) {
      this.objectPool.push({});
      this.arrayPool.push([]);
    }
  }

  /**
   * 객체 풀에서 객체 할당
   */
  allocateObject() {
    if (this.options.enableMemoryPool && this.objectPool.length > 0) {
      return this.objectPool.pop();
    }
    return {};
  }

  /**
   * 객체를 풀에 반환
   */
  deallocateObject(obj) {
    if (this.options.enableMemoryPool) {
      // 객체 초기화
      for (const key in obj) {
        delete obj[key];
      }
      this.objectPool.push(obj);
    }
  }

  /**
   * 배열 풀에서 배열 할당
   */
  allocateArray(size = 0) {
    if (this.options.enableMemoryPool && this.arrayPool.length > 0) {
      const arr = this.arrayPool.pop();
      arr.length = 0; // 초기화
      return arr;
    }
    return new Array(size);
  }

  /**
   * 배열을 풀에 반환
   */
  deallocateArray(arr) {
    if (this.options.enableMemoryPool) {
      arr.length = 0;
      this.arrayPool.push(arr);
    }
  }

  /**
   * 직접 접근을 위한 변수 캐시
   */
  cacheVariable(name) {
    if (this.options.enableDirectAccess && !this.accessCache.has(name)) {
      const value = this.variables.get(name);
      if (value !== undefined) {
        this.accessCache.set(name, value);
      }
    }
  }

  /**
   * 변수 접근 (최적화)
   */
  getVariable(name) {
    // 캐시에서 먼저 확인
    if (this.options.enableDirectAccess && this.accessCache.has(name)) {
      return this.accessCache.get(name);
    }

    // 원본 저장소에서 조회
    const value = this.variables.get(name);

    // 캐시 업데이트
    if (value !== undefined) {
      this.cacheVariable(name);
    }

    return value;
  }

  /**
   * 변수 설정 (캐시 무효화 포함)
   */
  setVariable(name, value) {
    this.variables.set(name, value);
    // 캐시 무효화
    if (this.options.enableDirectAccess) {
      this.accessCache.set(name, value);
    }
  }

  /**
   * 내장 함수 등록
   */
  registerBuiltinFunctions() {
    // Array 함수들
    this.registerFunction("Array.map", (arr, fn) => {
      const result = this.allocateArray(arr.length);
      for (let i = 0; i < arr.length; i++) {
        result[i] = fn(arr[i]);
      }
      return result;
    });

    this.registerFunction("Array.filter", (arr, fn) => {
      const result = this.allocateArray();
      for (let i = 0; i < arr.length; i++) {
        if (fn(arr[i])) {
          result.push(arr[i]);
        }
      }
      return result;
    });

    this.registerFunction("Array.reduce", (arr, fn, init) => {
      let acc = init;
      for (let i = 0; i < arr.length; i++) {
        acc = fn(acc, arr[i]);
      }
      return acc;
    });

    this.registerFunction("Array.find", (arr, fn) => {
      for (let i = 0; i < arr.length; i++) {
        if (fn(arr[i])) {
          return arr[i];
        }
      }
      return undefined;
    });

    // String 함수들
    this.registerFunction("String.split", (str, delimiter) => {
      return str.split(delimiter);
    });

    this.registerFunction("String.join", (arr, delimiter) => {
      return arr.join(delimiter);
    });

    this.registerFunction("String.upper", (str) => {
      return str.toUpperCase();
    });

    this.registerFunction("String.lower", (str) => {
      return str.toLowerCase();
    });

    this.registerFunction("String.trim", (str) => {
      return str.trim();
    });

    // Math 함수들
    this.registerFunction("Math.sqrt", (x) => Math.sqrt(x));
    this.registerFunction("Math.pow", (x, y) => Math.pow(x, y));
    this.registerFunction("Math.abs", (x) => Math.abs(x));

    // JSON 함수들
    this.registerFunction("JSON.parse", (str) => JSON.parse(str));
    this.registerFunction("JSON.stringify", (obj) => JSON.stringify(obj));

    // Print
    this.registerFunction("print", (value) => {
      this.output.push(String(value));
      console.log(value);
    });
  }

  /**
   * 함수 등록
   */
  registerFunction(name, fn) {
    this.functions.set(name, fn);
  }

  /**
   * 함수 호출
   */
  callFunction(name, args) {
    const fn = this.functions.get(name);
    if (!fn) {
      throw new Error(`Unknown function: ${name}`);
    }
    return fn(...args);
  }

  /**
   * VT 코드 라인 실행 (단순화된 버전)
   */
  executeLine(line) {
    if (!line || line.startsWith(";")) {
      return null; // 주석 또는 빈 줄
    }

    // 간단한 파싱 (실제로는 VT 인터프리터 필요)
    // 현재는 구조만 제시

    // (define x 42) 형태
    if (line.startsWith("(define ")) {
      const match = line.match(/\(define\s+(\w+)\s+(.+)\)/);
      if (match) {
        const varName = match[1];
        const value = this.evaluateExpression(match[2]);
        this.setVariable(varName, value);
        return value;
      }
    }

    // (call function arg1 arg2) 형태
    if (line.startsWith("(call ")) {
      const match = line.match(/\(call\s+(\S+)\s*(.*)\)/);
      if (match) {
        const funcName = match[1];
        const argsStr = match[2];
        const args = argsStr ? argsStr.split(/\s+/).map((a) => this.evaluateExpression(a)) : [];
        return this.callFunction(funcName, args);
      }
    }

    return null;
  }

  /**
   * 간단한 식 평가
   */
  evaluateExpression(expr) {
    // 숫자
    if (/^\d+$/.test(expr)) {
      return parseInt(expr);
    }

    // 문자열
    if (expr.startsWith('"') && expr.endsWith('"')) {
      return expr.slice(1, -1);
    }

    // 변수 참조
    if (/^[a-zA-Z_]\w*$/.test(expr)) {
      return this.getVariable(expr);
    }

    return expr;
  }

  /**
   * 전체 프로그램 실행
   */
  execute(vtCode) {
    const lines = vtCode.split("\n");
    const results = [];

    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed) {
        const result = this.executeLine(trimmed);
        if (result !== null && result !== undefined) {
          results.push(result);
        }
      }
    }

    return {
      success: true,
      results: results,
      output: this.output,
      variables: Object.fromEntries(this.variables),
    };
  }

  /**
   * 메모리 통계
   */
  getMemoryStats() {
    return {
      variableCount: this.variables.size,
      functionCount: this.functions.size,
      pooledObjects: this.objectPool.length,
      pooledArrays: this.arrayPool.length,
      accessCacheSize: this.accessCache.size,
      totalOutput: this.output.length,
    };
  }

  /**
   * 런타임 정리
   */
  cleanup() {
    this.variables.clear();
    this.accessCache.clear();
    this.output = [];

    if (this.options.enableMemoryPool) {
      this.objectPool = [];
      this.arrayPool = [];
      this.initializePools();
    }
  }

  /**
   * 성능 통계 출력
   */
  printStats() {
    const stats = this.getMemoryStats();
    console.log("\n");
    console.log("╔" + "═".repeat(50) + "╗");
    console.log("║" + " Runtime Statistics".padEnd(50) + "║");
    console.log("╠" + "═".repeat(50) + "╣");
    console.log(`║ Variables: ${stats.variableCount}`.padEnd(51) + "║");
    console.log(`║ Functions: ${stats.functionCount}`.padEnd(51) + "║");
    console.log(`║ Pooled Objects: ${stats.pooledObjects}`.padEnd(51) + "║");
    console.log(`║ Access Cache: ${stats.accessCacheSize}`.padEnd(51) + "║");
    console.log("╚" + "═".repeat(50) + "╝\n");
  }
}

module.exports = OptimizedVTRuntime;

/**
 * CLAUDELang v6.0 Batch Processor
 * 대량 컴파일/실행 병렬 처리
 *
 * 최적화:
 * 1. 워커 스레드를 사용한 병렬 처리
 * 2. 배치 큐 관리
 * 3. 결과 수집 및 병합
 * 4. 에러 처리
 */

const { Worker } = require("worker_threads");
const os = require("os");
const path = require("path");

class BatchProcessor {
  constructor(options = {}) {
    this.workerCount = options.workerCount || Math.min(os.cpus().length, 4);
    this.batchSize = options.batchSize || 10;
    this.timeout = options.timeout || 30000; // 30초
    this.workers = [];
    this.queue = [];
    this.results = [];
    this.isRunning = false;

    this.initializeWorkers();
  }

  /**
   * 워커 초기화
   */
  initializeWorkers() {
    // 워커 스레드는 실제 환경에서만 사용 가능
    // 테스트 환경에서는 메인 스레드에서 실행
    if (typeof Worker === "undefined") {
      console.warn("Worker threads not available, using main thread");
      this.useMainThread = true;
    }
  }

  /**
   * 배치에 작업 추가
   */
  addJob(program, id = null) {
    this.queue.push({
      id: id || `job_${this.queue.length}`,
      program: program,
      status: "pending",
      result: null,
    });
  }

  /**
   * 여러 작업 추가
   */
  addJobs(programs) {
    programs.forEach((program, idx) => {
      this.addJob(program, `job_${idx}`);
    });
  }

  /**
   * 배치 처리 (메인 스레드)
   */
  async processBatchMainThread(compiler) {
    const startTime = process.hrtime.bigint();
    const processed = [];

    for (const job of this.queue) {
      try {
        job.status = "processing";
        const result = compiler.compile(job.program);
        job.result = result;
        job.status = "completed";
        processed.push({
          id: job.id,
          success: result.success,
          codeSize: result.code ? result.code.length : 0,
        });
      } catch (error) {
        job.status = "failed";
        job.error = error.message;
        processed.push({
          id: job.id,
          success: false,
          error: error.message,
        });
      }
    }

    const endTime = process.hrtime.bigint();
    const elapsedMs = Number(endTime - startTime) / 1000000;

    return {
      total: this.queue.length,
      completed: processed.filter((p) => p.success).length,
      failed: processed.filter((p) => !p.success).length,
      timeMs: elapsedMs,
      avgTimeMs: elapsedMs / this.queue.length,
      results: processed,
    };
  }

  /**
   * 배치 처리
   */
  async process(compiler) {
    this.isRunning = true;
    this.results = [];

    const startTime = process.hrtime.bigint();

    // 메인 스레드에서 처리 (현재 환경)
    const result = await this.processBatchMainThread(compiler);

    const endTime = process.hrtime.bigint();
    const totalMs = Number(endTime - startTime) / 1000000;

    return {
      ...result,
      totalMs: totalMs,
    };
  }

  /**
   * 배치 재시도 (실패한 작업)
   */
  async retryFailed(compiler, maxRetries = 3) {
    const failed = this.queue.filter((job) => job.status === "failed");

    if (failed.length === 0) {
      return { retried: 0, fixed: 0 };
    }

    let fixed = 0;
    for (const job of failed) {
      for (let attempt = 1; attempt <= maxRetries; attempt++) {
        try {
          const result = compiler.compile(job.program);
          job.result = result;
          job.status = "completed";
          fixed++;
          break;
        } catch (error) {
          if (attempt === maxRetries) {
            job.error = `Failed after ${maxRetries} attempts: ${error.message}`;
          }
        }
      }
    }

    return { retried: failed.length, fixed: fixed };
  }

  /**
   * 진행 상황 조회
   */
  getProgress() {
    const total = this.queue.length;
    const completed = this.queue.filter((j) => j.status === "completed").length;
    const failed = this.queue.filter((j) => j.status === "failed").length;
    const processing = this.queue.filter((j) => j.status === "processing").length;

    return {
      total: total,
      completed: completed,
      processing: processing,
      pending: total - completed - failed - processing,
      failed: failed,
      progressPercent: total === 0 ? 0 : (completed / total) * 100,
    };
  }

  /**
   * 결과 요약
   */
  getSummary() {
    const successful = this.queue.filter((j) => j.status === "completed" && j.result?.success);
    const failed = this.queue.filter((j) => j.status === "failed" || (j.result && !j.result.success));

    const totalCodeSize = successful.reduce((sum, job) => {
      return sum + (job.result?.code?.length || 0);
    }, 0);

    return {
      totalJobs: this.queue.length,
      successful: successful.length,
      failed: failed.length,
      totalCodeSize: totalCodeSize,
      avgCodeSize: totalCodeSize / Math.max(successful.length, 1),
    };
  }

  /**
   * 배치 초기화
   */
  clear() {
    this.queue = [];
    this.results = [];
    this.isRunning = false;
  }

  /**
   * 배치 상태 출력
   */
  printStatus() {
    const progress = this.getProgress();
    const summary = this.getSummary();

    console.log("\n");
    console.log("╔" + "═".repeat(60) + "╗");
    console.log("║" + " Batch Processing Status".padEnd(60) + "║");
    console.log("╠" + "═".repeat(60) + "╣");
    console.log(`║ Total Jobs: ${progress.total}`.padEnd(61) + "║");
    console.log(`║ Completed: ${progress.completed} | Processing: ${progress.processing} | Pending: ${progress.pending}`.padEnd(61) + "║");
    console.log(`║ Failed: ${progress.failed}`.padEnd(61) + "║");
    console.log(`║ Progress: ${progress.progressPercent.toFixed(1)}%`.padEnd(61) + "║");
    console.log("╠" + "═".repeat(60) + "╣");
    console.log(`║ Successful Compilations: ${summary.successful}`.padEnd(61) + "║");
    console.log(`║ Failed Compilations: ${summary.failed}`.padEnd(61) + "║");
    console.log(`║ Total Code Size: ${summary.totalCodeSize} bytes`.padEnd(61) + "║");
    console.log(`║ Avg Code Size: ${summary.avgCodeSize.toFixed(0)} bytes`.padEnd(61) + "║");
    console.log("╚" + "═".repeat(60) + "╝\n");
  }

  /**
   * 결과를 JSON으로 내보내기
   */
  exportResults(filename = "batch-results.json") {
    const fs = require("fs");
    const summary = this.getSummary();
    const progress = this.getProgress();

    const report = {
      timestamp: new Date().toISOString(),
      summary: summary,
      progress: progress,
      jobs: this.queue.map((job) => ({
        id: job.id,
        status: job.status,
        success: job.result?.success || false,
        codeSize: job.result?.code?.length || 0,
        error: job.error || null,
      })),
    };

    fs.writeFileSync(filename, JSON.stringify(report, null, 2));
    console.log(`✅ Results exported to ${filename}`);

    return report;
  }
}

