    });

    // 캐시 효과 검증
    if (test2.time_ms < test1.time_ms) {
      console.log(
        `${colors.green}✅ Caching effective: ${(test1.time_ms / test2.time_ms).toFixed(1)}x faster${colors.reset}`
      );
