            content: `Performance Report - ${new Date().toISOString()}`
          }
        }
      ],
      "Compile Time (ms)": {
        number: basicCompile.time_ms
      },
      "Cache Hit Rate": {
        rich_text: [{ text: { content: "50%" } }]
      },
      "Status": {
        select: { name: basicCompile.time_ms < 1.0 ? "Good" : "Degraded" }
      }
    }
  });
}
